('1294/QĐ-UBND', '1BC3B52B6BB04B2347258E0A000E994B', '2026-06-01', '2026-06-01', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính được sửa đổi, bổ sung và bị bãi bỏ thuộc phạm vi quản lý của Bộ Nội vụ tại Nghị quyết số 24/2026/NQCP ngày 29/4/2026 về cắt giảm, phân cấp, đơn giản hóa thủ tục hành chính, điều kiện kinh doanh lĩnh vực nội vụ', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/1BC3B52B6BB04B2347258E0A000E994B/$file/QD 1294_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1294_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=1BC3B52B6BB04B2347258E0A000E994B', '2026-08-06 08:32:26'),
('16/2026/NQ-HĐND', '1D13CBD860A3A33D47258E3E0007614C', '2026-07-21', '2026-08-01', NULL, 'HĐND Tỉnh', 'Nghị quyết của HĐND tỉnh', NULL, 'Chủ tịch HĐND Lò Minh Hùng', 'Bãi bỏ Nghị quyết số 110/2025/NQ-HĐND ngày 29 tháng 04 năm 2025 của HĐND tỉnh quy định thẩm quyền quyết định thanh lý rừng trồng trên địa bàn tỉnh Sơn La', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/1D13CBD860A3A33D47258E3E0007614C/$file/NQ so 16.2026.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\16_2026_NQ-HĐND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=1D13CBD860A3A33D47258E3E0007614C', '2026-08-06 08:04:56'),
('1341/QĐ-UBND', '1D98DA5B487FDFD247258E110013C2C6', '2026-06-04', '2026-06-04', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính được sửa đổi, bổ sung  trong lĩnh vực Đường bộ thuộc phạm vi chức năng quản lý nhà nước của Sở Xây dựng', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/1D98DA5B487FDFD247258E110013C2C6/$file/QD 1341.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1341_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=1D98DA5B487FDFD247258E110013C2C6', '2026-08-06 08:28:56'),
('21/NQ-HĐND', '1DE788D3CBED7CC347258E2600290E62', '2026-06-26', '2026-06-26', NULL, 'HĐND xã Chiềng Mai', 'Nghị quyết HĐND xã', NULL, 'Chủ tịch HĐND Hà Văn Bình', 'Về việc phê duyệt kế hoạch sử dụng tiền dịch vụ môi trường rừng phục vụ công tác quản lý, bảo vệ rừng năm 2026', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/1DE788D3CBED7CC347258E2600290E62/$file/NQ 21.CMai.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\21_NQ-HĐND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=1DE788D3CBED7CC347258E2600290E62', '2026-08-06 08:16:43'),
('18/2026/NQ-HĐND', '1DF0483BE048181047258E3E0007C9E6', '2026-07-21', '2026-08-01', NULL, 'HĐND Tỉnh', 'Nghị quyết của HĐND tỉnh', NULL, 'Chủ tịch HĐND Lò Minh Hùng', 'Ban hành Quy định nội dung, mức chi thực hiện chương trình, nhiệm vụ khoa học, công nghệ và đổi mới sáng tạo; hoạt động hỗ trợ có sử dụng ngân sách nhà nước thuộc phạm vi quản lý của tỉnh.', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/1DF0483BE048181047258E3E0007C9E6/$file/NQ so 18.2026.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\18_2026_NQ-HĐND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=1DF0483BE048181047258E3E0007C9E6', '2026-08-06 08:04:06'),
('1374/QĐ-UBND', '1F9E81ACDD1CBB8147258E1400155076', '2026-06-09', '2026-07-01', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính được sửa đổi, bổ sung và bị bãi bỏ trong lĩnh vực Thủy sản và Kiểm ngư thuộc phạm vi chức năng quản lý nhà nước của Sở Nông nghiệp và Môi trường', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/1F9E81ACDD1CBB8147258E1400155076/$file/QD 1374.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1374_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=1F9E81ACDD1CBB8147258E1400155076', '2026-08-06 08:26:57'),
('1167/QĐ-UBND', '20159607DAC308D747258DFC00177771', '2026-05-18', '2026-05-18', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính mới ban hành; được sửa đổi, bổ sung và bị bãi bỏ lĩnh vực Trồng trọt và Bảo vệ thực vật; lĩnh vực Tài nguyên nước thuộc phạm vi chức năng quản lý nhà nước của Sở Nông nghiệp và Môi trường', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/20159607DAC308D747258DFC00177771/$file/QD 1167_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1167_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=20159607DAC308D747258DFC00177771', '2026-08-06 08:38:16'),
('1196/QĐ-UBND', '205AA88164BA524D47258DFE000AB581', '2026-05-20', '2026-05-20', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Nguyễn Thành Công', 'Về việc thu hồi đất của Công ty trách nhiệm hữu hạn Cao Nguyên, giao cho UBND phường Vân Sơn để quản lý; chuyển mục đích sử dụng đất, giao đất cho Trung tâm xúc tiến đầu tư, Thương mại và Du lịch tỉnh để quản lý, sử dụng và cho Công ty cổ phần Highland Grands thuê đất để thực hiện dự án Tổ hợp khách sạn, nghỉ dưỡng kết hợp nông nghiệp sinh thái Highland Grands', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/205AA88164BA524D47258DFE000AB581/$file/QD 1196_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1196_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=205AA88164BA524D47258DFE000AB581', '2026-08-06 08:37:52'),
('1310/QĐ-UBND', '210551719C42769D47258E0B0031BFB3', '2026-06-02', '2026-06-02', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Chủ tịch UBND Nguyễn Đình Việt', 'Về việc kiện toàn Ban Chỉ đạo của UBND tỉnh Sơn La về phát triển khoa học, công nghệ, đổi mới sáng tạo, chuyển đổi số và Đề án 06', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/210551719C42769D47258E0B0031BFB3/$file/QD 1310_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1310_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=210551719C42769D47258E0B0031BFB3', '2026-08-06 08:31:05'),
('1118/QĐ-UBND', '2130AA6C8B54648D47258DF60036757D', '2026-05-12', '2026-05-12', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính mới ban hành trong lĩnh vực Tài sản đất đai thuộc phạm vi chức năng quản lý nhà nước của Sở Tài chính', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/2130AA6C8B54648D47258DF60036757D/$file/QD 1118_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1118_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=2130AA6C8B54648D47258DF60036757D', '2026-08-06 08:41:46'),
('1342/QĐ-UBND', '21AE2DBE507D46C647258E11001373A5', '2026-06-04', '2026-06-04', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc thay đổi Danh sách cán bộ, công chức làm đầu mối thực hiện nhiệm vụ kiểm soát thủ tục hành chính của Sở Tài chính tại Quyết định số 740/QĐ-UBND ngày 01/4/2025 của Chủ tịch UBND tỉnh', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/21AE2DBE507D46C647258E11001373A5/$file/QD 1342.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1342_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=21AE2DBE507D46C647258E11001373A5', '2026-08-06 08:28:47'),
('1259/QĐ-UBND', '2202451A3398774247258E0500148941', '2026-05-27', '2026-05-27', NULL, 'UBND Tỉnh', 'Quyết định của UBND tỉnh', NULL, 'Phó Chủ tịch UBND Nguyễn Thành Công', 'Giấy phép sử dụng vật liệu nổ công nghiệp (Cấp cho Công ty TNHH SORICOM để đào phá đá thi công Gói thầu số 19 thuộc Dự án “Đường giao thông từ bản Hua Chiến, xã Chiềng Muôn đến đập thủy điện Nậm Chiến, xã Ngọc Chiến, huyện Mường La (nay là xã Mường La và xã Ngọc Chiến, tỉnh Sơn La)”).', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/2202451A3398774247258E0500148941/$file/QD 1259_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1259_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=2202451A3398774247258E0500148941', '2026-08-06 08:34:33'),
('1603/QĐ-UBND', '22518BAD2DB0530047258E27002E9235', '2026-07-01', '2026-07-01', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính trong lĩnh vực bồi thường nhà nước thuộc phạm vi chức năng quản lý nhà nước của Sở Tư pháp', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/22518BAD2DB0530047258E27002E9235/$file/QD 1603.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1603_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=22518BAD2DB0530047258E27002E9235', '2026-08-06 08:15:13'),
