('1290/QĐ-UBND', '24234C7C9220E66A47258E0A000D51BA', '2026-05-31', '2026-05-31', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Chủ tịch UBND Nguyễn Đình Việt', 'Phê duyệt kết quả mời quan tâm thực hiện Dự án Cơ sở giáo dục đào tạo, giáo dục nghề nghiệp', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/24234C7C9220E66A47258E0A000D51BA/$file/QD 1290_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1290_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=24234C7C9220E66A47258E0A000D51BA', '2026-08-06 08:32:57'),
('41/NQ-HĐND', '244AA60B8E1C062A47258E3E00091933', '2026-07-21', '2026-07-21', NULL, 'HĐND Tỉnh', 'Nghị quyết của HĐND tỉnh', NULL, 'Chủ tịch HĐND Lò Minh Hùng', 'Phê duyệt chủ trương chuyển mục đích sử dụng rừng sang mục đích khác để thực hiện 02 dự án: Bố trí sắp xếp dân cư vùng thiên tai các bản thuộc xã Tường Hạ và dự án Đường giao thông từ trung tâm xã Chiềng Muôn - xã Chiềng Ân (nay là xã Mường La, xã Chiềng Hoa) tỉnh Sơn La', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/244AA60B8E1C062A47258E3E00091933/$file/NQ so 41.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\41_NQ-HĐND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=244AA60B8E1C062A47258E3E00091933', '2026-08-06 08:03:19'),
('1546/QĐ-UBND', '24EF79FA23D12D7547258E2100352117', '2026-06-25', '2026-06-25', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính mới ban hành và được thay thế trong lĩnh vực Giáo dục nghề nghiệp thuộc phạm vi chức năng quản lý nhà nước của Sở Giáo dục và Đào tạo', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/24EF79FA23D12D7547258E2100352117/$file/QD 1546.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1546_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=24EF79FA23D12D7547258E2100352117', '2026-08-06 08:18:13'),
('1045/QĐ-UBND', '24EFED358072A73547258DF0000C8C04', '2026-04-28', '2026-04-28', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Chủ tịch UBND Nguyễn Đình Việt', 'V/v phân công nhiệm vụ của Chủ tịch, các Phó Chủ tịch và các Ủy viên Ủy ban nhân dân tỉnh Sơn La, nhiệm kỳ 2026-2031.', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/24EFED358072A73547258DF0000C8C04/$file/QD so 1045_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1045_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=24EFED358072A73547258DF0000C8C04', '2026-08-06 08:45:46'),
('1903/QĐ-UBND', '252EDC72347B5FAC47258E430034D9D5', '2026-07-29', '2026-07-29', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch Thường trực UBND tỉnh Hà Trung Chiến', 'Ban hành Kế hoạch rà soát, đánh giá, hoàn thiện các điều kiện, tiêu chí, thẩm định, công nhận Khu du lịch Ngọc Chiến, tỉnh Sơn La', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/252EDC72347B5FAC47258E430034D9D5/$file/QD 1903.pdf;https://congbao.sonla.gov.vn/congbao.nsf/252EDC72347B5FAC47258E430034D9D5/$file/QD 1903.F1.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1903_QĐ-UBND.pdf;D:\\Congpv\\Python\\data_congbao\\downloads\\1903_QĐ-UBND_1.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=252EDC72347B5FAC47258E430034D9D5', '2026-08-06 07:57:13'),
('1088/QĐ-UBND', '25FBF1575B2A2E9347258DEF002A24B3', '2026-05-05', '2026-05-05', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc cấp Chứng chỉ hành nghề luật sư', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/25FBF1575B2A2E9347258DEF002A24B3/$file/QD 1088_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1088_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=25FBF1575B2A2E9347258DEF002A24B3', '2026-08-06 08:42:26'),
('1270/QĐ-UBND', '26952F7E2F12EEFF47258E0600160E2E', '2026-05-29', '2026-05-29', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính mới ban hành và được sửa đổi, bổ sung lĩnh vực hoạt động khoa học và công nghệ thuộc phạm vi chức năng quản lý nhà nước của Sở Khoa học và Công nghệ', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/26952F7E2F12EEFF47258E0600160E2E/$file/QD 1270_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1270_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=26952F7E2F12EEFF47258E0600160E2E', '2026-08-06 08:33:50'),
('1558/QĐ-UBND', '269CDA1F765C967547258E26002758D7', '2026-06-27', '2026-06-27', NULL, 'UBND Tỉnh', 'Quyết định của UBND tỉnh', NULL, 'Phó Chủ tịch UBND Nguyễn Minh Tiến', 'Phê duyệt nhiệm vụ quy hoạch chung xã Tường Hạ, tỉnh Sơn La đến năm 2045', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/269CDA1F765C967547258E26002758D7/$file/QD 1558.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1558_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=269CDA1F765C967547258E26002758D7', '2026-08-06 08:16:24'),
('37/NQ-HĐND', '27EAF685904654FE47258E3E00089129', '2026-07-20', '2026-07-20', NULL, 'HĐND Tỉnh', 'Nghị quyết của HĐND tỉnh', NULL, 'Chủ tịch HĐND Lò Minh Hùng', 'Về việc phân bổ kế hoạch đầu tư công năm 2026 nguồn vốn ngân sách địa phương (đợt 4).', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/27EAF685904654FE47258E3E00089129/$file/NQ so 37.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\37_NQ-HĐND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=27EAF685904654FE47258E3E00089129', '2026-08-06 08:05:59'),
('1135/QĐ-UBND', '28958414D28DCEC347258DF700169499', '2026-05-13', '2026-05-13', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính sửa đổi, bổ sung và bị bãi bỏ trong lĩnh vực Quản lý chất lượng công trình xây dựng, Hàng hải và Đường thủy nội địa thuộc phạm vi chức năng quản lý nhà nước của Sở Xây dựng', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/28958414D28DCEC347258DF700169499/$file/QD 1135_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1135_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=28958414D28DCEC347258DF700169499', '2026-08-06 08:40:21'),
('1672/QĐ-UBND', '29D070A9F03EE67D47258E2D0036ACB4', '2026-07-06', '2026-07-06', NULL, 'UBND Tỉnh', 'Quyết định của UBND tỉnh', NULL, 'Phó Chủ tịch UBND Nguyễn Thành Công', 'Về việc phê duyệt chủ trương và dự kiến kinh phí thực hiện dự án Sửa đổi, bảng giá đất quy định tại Nghị quyết 152/2025/NQ-HĐND ngày 29/12/2025 của HĐND tỉnh', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/29D070A9F03EE67D47258E2D0036ACB4/$file/QD 1672.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1672_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=29D070A9F03EE67D47258E2D0036ACB4', '2026-08-06 08:12:22'),
('1104/QĐ-UBND', '2B683A1B72BF9B7647258DF500120918', '2026-05-09', '2026-05-09', NULL, 'UBND Tỉnh', 'Quyết định của UBND tỉnh', NULL, 'Phó Chủ tịch UBND Nguyễn Minh Tiến', 'Phê duyệt nhiệm vụ quy hoạch chung xã Mường Chanh, tỉnh Sơn La đến năm 2045', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/2B683A1B72BF9B7647258DF500120918/$file/QD 1104_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1104_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=2B683A1B72BF9B7647258DF500120918', '2026-08-06 08:42:15'),
('1879/QĐ-UBND', '2B95262C34A064E447258E42002E4607', '2026-07-23', '2026-07-23', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Chủ tịch UBND Nguyễn Đình Việt', 'Về việc chấp thuận chủ trương đầu tư đồng thời chấp thuận nhà đầu tư dự án Nhà máy điện mặt trời Bắc Yên 2.', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/2B95262C34A064E447258E42002E4607/$file/QD 1879.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1879_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=2B95262C34A064E447258E42002E4607', '2026-08-06 08:01:35'),
('1555/QĐ-UBND', '2EA3FBF175973B2447258E210034D079', '2026-06-25', '2026-06-25', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Chủ tịch UBND Nguyễn Đình Việt', 'Phê duyệt kết quả lựa chọn nhà đầu tư Dự án Khu đô thị sinh thái trị liệu giữa mây trời Vân Hồ', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/2EA3FBF175973B2447258E210034D079/$file/QD 1555.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1555_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=2EA3FBF175973B2447258E210034D079', '2026-08-06 08:17:54'),
('1177/QĐ-UBND', '2FFD64304C18507A47258DFE000A4FBF', '2026-05-19', '2026-05-19', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính được sửa đổi, bổ sung liên quan đến người lao động nước ngoài làm việc tại Việt Nam lĩnh vực việc làm thuộc phạm vi chức năng quản lý nhà nước của Sở Nội vụ', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/2FFD64304C18507A47258DFE000A4FBF/$file/QD 1177_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1177_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=2FFD64304C18507A47258DFE000A4FBF', '2026-08-06 08:38:07'),
('1683/QĐ-UBND', '3153CC0F24366F1F47258E2D0037F2DA', '2026-07-07', '2026-07-07', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Nguyễn Thành Công', 'Về việc phê duyệt kết quả thẩm định báo cáo đánh giá tác động môi trường của dự án Đầu tư khai thác đá làm nguyên liệu sản xuất cát tại tổ dân phố Bó Bun, phường Vân Sơn, tỉnh Sơn La', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/3153CC0F24366F1F47258E2D0037F2DA/$file/QD 1683.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1683_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=3153CC0F24366F1F47258E2D0037F2DA', '2026-08-06 08:11:52'),
('1313/QĐ-UBND', '327AB2F7BEE0BE7147258E0B00358964', '2026-06-02', '2026-06-02', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính được sửa đổi, bổ sung lĩnh vực An toàn bức xạ và hạt nhân thuộc phạm vi chức năng quản lý nhà nước của Sở Khoa học và Công nghệ', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/327AB2F7BEE0BE7147258E0B00358964/$file/QD 1313_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1313_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=327AB2F7BEE0BE7147258E0B00358964', '2026-08-06 08:30:35'),
('82/NQ-HĐND', '334DFF5B87E30B5547258DD8002D9EC8', '2026-03-31', '2026-03-31', NULL, 'HĐND Tỉnh', 'Nghị quyết của Thường trực HĐND tỉnh', NULL, 'Chủ tịch HĐND Lò Minh Hùng', 'Phê chuẩn kết quả bầu Phó Chủ tịch Hội đồng nhân dân xã Muổi Nọi khoá XXII, nhiệm kỳ 2026 - 2031', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/334DFF5B87E30B5547258DD8002D9EC8/$file/NQ 82.tinh_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\82_NQ-HĐND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=334DFF5B87E30B5547258DD8002D9EC8', '2026-08-06 08:52:55'),
('1228/QĐ-UBND', '3367CC0AF3523B4347258E02000E45FE', '2026-05-25', '2026-05-25', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính nội bộ mới ban hành lĩnh vực Chế độ, chính sách đối với nhà giáo thuộc phạm vi chức năng quản lý nhà nước của Sở Giáo dục và Đào tạo', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/3367CC0AF3523B4347258E02000E45FE/$file/QD 1228_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1228_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=3367CC0AF3523B4347258E02000E45FE', '2026-08-06 08:36:09');
