('1709/QĐ-UBND', '33C41E329202302A47258E33000E1EEA', '2026-07-09', '2026-07-09', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính mới ban hành, được thay thế và bị bãi bỏ trong lĩnh vực Hoạt động xây dựng thuộc phạm vi chức năng quản lý nhà nước của Sở Xây dựng', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/33C41E329202302A47258E33000E1EEA/$file/QD 1709.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1709_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=33C41E329202302A47258E33000E1EEA', '2026-08-06 08:10:46'),
('1299/QĐ-UBND', '3411DB935E591E3C47258E0A000EE425', '2026-06-01', '2026-06-01', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc phê duyệt danh sách cán bộ, công chức làm đầu mối thực hiện nhiệm vụ kiểm soát thủ tục hành chính của Sở Ngoại vụ', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/3411DB935E591E3C47258E0A000EE425/$file/QD 1299_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1299_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=3411DB935E591E3C47258E0A000EE425', '2026-08-06 08:32:00'),
('14/NQ-HĐND', '3431EBF58B68B35647258DFC0016BCCF', '2026-05-12', '2026-05-12', NULL, 'HĐND xã Mường Chanh', 'Nghị quyết HĐND xã', NULL, 'Chủ tịch HĐND Nguyễn Thị Hải Yến', 'Về việc điều chỉnh quyết toán ngân sách địa phương năm 2025', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/3431EBF58B68B35647258DFC0016BCCF/$file/NQ 14.MChanh_signed.pdf;https://congbao.sonla.gov.vn/congbao.nsf/3431EBF58B68B35647258DFC0016BCCF/$file/NQ.F1.MChanh_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\14_NQ-HĐND.pdf;D:\\Congpv\\Python\\data_congbao\\downloads\\14_NQ-HĐND_1.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=3431EBF58B68B35647258DFC0016BCCF', '2026-08-06 08:40:31'),
('1234/QĐ-UBND', '352A8355D44D308947258E03002A2ED2', '2026-05-26', '2026-05-26', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính mới ban hành và bị bãi bỏ trong lĩnh vực Chăn nuôi và Thú y thuộc phạm vi chức năng quản lý nhà nước của Sở Nông nghiệp và Môi trường', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/352A8355D44D308947258E03002A2ED2/$file/QD 1234_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1234_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=352A8355D44D308947258E03002A2ED2', '2026-08-06 08:35:20'),
('23/QĐ-TT HĐND', '3547C09957A338D447258E4A00084E05', '2026-08-04', '2026-08-04', NULL, 'HĐND Tỉnh', 'Nghị quyết của Thường trực HĐND tỉnh', NULL, 'Phó Chủ tịch HĐND Nguyễn Việt Cường', 'Về việc điều chỉnh Danh mục ban hành kèm theo Quyết định số 120/QĐTTHĐND ngày 26/02/2026 của Thường trực HĐND tỉnh ban hành Danh mục Nghị quyết của HĐND tỉnh quy định các nội dung được giao tại các luật, nghị quyết của Quốc hội khoá XV thông qua tại Kỳ họp thứ 10 và Thông tư của Bộ trưởng Bộ Khoa học và Công nghệ', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/3547C09957A338D447258E4A00084E05/$file/QD so 23. TT HĐND.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\23_QĐ-TT_HĐND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=3547C09957A338D447258E4A00084E05', '2026-08-06 07:54:26'),
('1271/QĐ-UBND', '35C9D1F89F9CC1E447258E0600172F04', '2026-05-29', '2026-05-29', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Công bố danh sách tổ chức, cá nhân giám định tư pháp trên địa bàn tỉnh Sơn La', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/35C9D1F89F9CC1E447258E0600172F04/$file/QD 1271_signed.pdf;https://congbao.sonla.gov.vn/congbao.nsf/35C9D1F89F9CC1E447258E0600172F04/$file/QD 1271.F1_signed.pdf;https://congbao.sonla.gov.vn/congbao.nsf/35C9D1F89F9CC1E447258E0600172F04/$file/QD 1271.F2_signed.pdf;https://congbao.sonla.gov.vn/congbao.nsf/35C9D1F89F9CC1E447258E0600172F04/$file/QD 1271.F3_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1271_QĐ-UBND.pdf;D:\\Congpv\\Python\\data_congbao\\downloads\\1271_QĐ-UBND_1.pdf;D:\\Congpv\\Python\\data_congbao\\downloads\\1271_QĐ-UBND_2.pdf;D:\\Congpv\\Python\\data_congbao\\downloads\\1271_QĐ-UBND_3.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=35C9D1F89F9CC1E447258E0600172F04', '2026-08-06 08:33:40'),
('1520/QĐ-UBND', '36A619F0BE12DB9347258E200030C2F3', '2026-06-23', '2026-06-23', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính được sửa đổi, bổ sung, thay thế và bị bãi bỏ lĩnh vực Giáo dục mầm non, Giáo dục tiểu học, Giáo dục trung học, Giáo dục thường xuyên, Cơ sở giáo dục khác, Giáo dục nghề nghiệp, Giáo dục đào tạo với nước ngoài thuộc phạm vi chức năng quản lý nhà nước của Sở Giáo dục và Đào tạo', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/36A619F0BE12DB9347258E200030C2F3/$file/QD 1520.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1520_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=36A619F0BE12DB9347258E200030C2F3', '2026-08-06 08:19:44'),
('1139/QĐ-UBND', '37442336A0B8BB3D47258DF70016BAB2', '2026-05-13', '2026-05-13', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính sửa đổi, bổ sung trong lĩnh vực Nhà ở, Vật liệu xây dựng thuộc phạm vi chức năng quản lý nhà nước của Sở Xây dựng', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/37442336A0B8BB3D47258DF70016BAB2/$file/QD 1139_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1139_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=37442336A0B8BB3D47258DF70016BAB2', '2026-08-06 08:39:44'),
('42/NQ-HĐND', '379A46C9F36EBBD447258E3E00094405', '2026-07-21', '2026-07-21', NULL, 'HĐND Tỉnh', 'Nghị quyết của HĐND tỉnh', NULL, 'Chủ tịch HĐND Lò Minh Hùng', 'Thông qua danh mục thu hồi đất để thực hiện dự án phát triển kinh tế - xã hội vì lợi ích quốc gia, công cộng trên địa bàn tỉnh.', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/379A46C9F36EBBD447258E3E00094405/$file/NQ so 42.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\42_NQ-HĐND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=379A46C9F36EBBD447258E3E00094405', '2026-08-06 08:03:07'),
