('973/QĐ-UBND', '4860E8E3D02AF51047258DE100117376', '2026-04-20', '2026-04-20', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính được sửa đổi, bổ sung, thay thế và bị bãi bỏ trong lĩnh vực Giáo dục mầm non, giáo dục trung học, giáo dục nghề nghiệp, giáo dục và đào tạo thuộc hệ thống giáo dục quốc dân thuộc phạm vi chức năng quản lý nhà nước của Sở Giáo dục và Đào tạo', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/4860E8E3D02AF51047258DE100117376/$file/QD 973_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\973_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=4860E8E3D02AF51047258DE100117376', '2026-08-06 08:47:38'),
('888/QĐ-UBND', '48EFC0CA19D4A1F347258DD8003137B7', '2026-04-08', '2026-04-08', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Chủ tịch UBND Nguyễn Đình Việt', 'Ủy quyền cho Giám đốc Sở Nông nghiệp và Môi trường thực hiện một số nhiệm vụ thuộc thẩm quyền của Chủ tịch Ủy ban nhân dân tỉnh thuộc lĩnh vực chăn nuôi, thú y và thuỷ sản', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/48EFC0CA19D4A1F347258DD8003137B7/$file/QD 880_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\888_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=48EFC0CA19D4A1F347258DD8003137B7', '2026-08-06 08:51:33'),
