('1360/QĐ-UBND', '619B264C6F033C0B47258E1100156BBF', '2026-06-07', '2026-06-07', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính mới ban hành lĩnh vực Viễn thông và Internet; Công nghiệp công nghệ số thuộc phạm vi chức năng quản lý nhà nước của Sở Khoa học và Công nghệ', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/619B264C6F033C0B47258E1100156BBF/$file/QD 1360_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1360_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=619B264C6F033C0B47258E1100156BBF', '2026-08-06 08:28:01'),
('1001/QĐ-UBND', '624A9F0B654780BB47258DE3000B3977', '2026-04-23', '2026-04-23', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính bị bãi bỏ lĩnh vực Quản lý công sản và Thành lập, sắp xếp lại doanh nghiệp do Nhà nước nắm giữ 100% vốn điều lệ thuộc phạm vi chức năng quản lý nhà nước của Sở Tài chính', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/624A9F0B654780BB47258DE3000B3977/$file/QD 1001_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1001_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=624A9F0B654780BB47258DE3000B3977', '2026-08-06 08:46:19'),
('1902/QĐ-UBND', '631CCA76C24953C747258E4300341679', '2026-07-29', '2026-07-29', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch Thường trực UBND tỉnh Hà Trung Chiến', 'Ban hành Kế hoạch rà soát, đánh giá, hoàn thiện các điều kiện, tiêu chí, thẩm định, công nhận Khu du lịch cấp tỉnh Pha Đin, tỉnh Sơn La', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/631CCA76C24953C747258E4300341679/$file/QD 1902.pdf;https://congbao.sonla.gov.vn/congbao.nsf/631CCA76C24953C747258E4300341679/$file/QD 1902.F1.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1902_QĐ-UBND.pdf;D:\\Congpv\\Python\\data_congbao\\downloads\\1902_QĐ-UBND_1.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=631CCA76C24953C747258E4300341679', '2026-08-06 07:57:22'),
('1825/QĐ-UBND', '632FCE63AE820B6E47258E3C003107F2', '2026-07-22', '2026-07-22', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố thủ tục hành chính nội bộ mới ban hành  trong lĩnh vực Đường thủy nội địa thuộc phạm vi chức năng quản lý nhà nước của Sở Xây dựng', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/632FCE63AE820B6E47258E3C003107F2/$file/QD 1825.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1825_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=632FCE63AE820B6E47258E3C003107F2', '2026-08-06 08:02:10'),
('1382/QĐ-UBND', '63693B11B574066447258E1400168131', '2026-06-11', '2026-06-11', NULL, 'UBND Tỉnh', 'Quyết định của UBND tỉnh', NULL, 'Phó Chủ tịch UBND Nguyễn Minh Tiến', 'Phê duyệt nhiệm vụ quy hoạch chung xã Huổi Một, tỉnh Sơn La đến năm 2045', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/63693B11B574066447258E1400168131/$file/QD 1382.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1382_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=63693B11B574066447258E1400168131', '2026-08-06 08:26:03'),
('1475/QĐ-UBND', '64D5A6519175E8BF47258E1E0032F76B', '2026-06-19', '2026-06-19', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính mới ban hành; được sửa đổi, bổ sung và bị bãi bỏ lĩnh vực Tần số vô tuyến điện thuộc phạm vi chức năng quản lý của Sở Khoa học và Công nghệ', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/64D5A6519175E8BF47258E1E0032F76B/$file/QD 1475.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1475_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=64D5A6519175E8BF47258E1E0032F76B', '2026-08-06 08:21:40'),
('61/NQ-HĐND', '64FD424ECFD63F1847258DD90030402F', '2026-03-31', '2026-03-31', NULL, 'HĐND Tỉnh', 'Nghị quyết của Thường trực HĐND tỉnh', NULL, 'Chủ tịch HĐND Lò Minh Hùng', 'Phê chuẩn kết quả bầu Chủ tịch Hội đồng nhân dân xã Lóng Sập khoá XXII, nhiệm kỳ 2026 - 2031', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/64FD424ECFD63F1847258DD90030402F/$file/NQ 61.tinh_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\61_NQ-HĐND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=64FD424ECFD63F1847258DD90030402F', '2026-08-06 08:54:05'),
('14/2026/NQ-HĐND', '6513D399B8C9219447258E3E000AE1AE', '2026-07-21', '2026-08-01', NULL, 'HĐND Tỉnh', 'Nghị quyết của HĐND tỉnh', NULL, 'Chủ tịch HĐND Lò Minh Hùng', 'Quy định nguyên tắc, tiêu chí, định mức phân bổ vốn ngân sách trung ương và tỷ lệ vốn đối ứng của ngân sách địa phương thực hiện Chương trình mục tiêu quốc gia xây dựng nông thôn mới, giảm nghèo bền vững và phát triển kinh tế - xã hội vùng đồng bào dân tộc thiểu số và miền núi giai đoạn 2026-2030 trên địa bàn tỉnh.', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/6513D399B8C9219447258E3E000AE1AE/$file/NQ so 14.2026.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\14_2026_NQ-HĐND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=6513D399B8C9219447258E3E000AE1AE', '2026-08-06 08:05:16'),
('1465/QĐ-UBND', '66D816DECDA4B9F547258E1A0031262A', '2026-06-18', '2026-06-18', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính được sửa đổi, bổ sung và bị bãi bỏ trong lĩnh vực Văn hóa; Du lịch thuộc phạm vi chức năng quản lý nhà nước của Sở Văn hóa, Thể thao và Du lịch', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/66D816DECDA4B9F547258E1A0031262A/$file/QD 1465.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1465_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=66D816DECDA4B9F547258E1A0031262A', '2026-08-06 08:22:02'),
('30/NQ-HĐND', '67A9222A3583D22047258E3E0007EB06', '2026-07-20', '2026-07-20', NULL, 'HĐND Tỉnh', 'Nghị quyết của HĐND tỉnh', NULL, 'Chủ tịch HĐND Lò Minh Hùng', 'Ban hành Quy chế tiếp công dân, tiếp nhận, phân loại, xử lý đơn và giám sát của Hội đồng nhân dân tỉnh khoá XVI, nhiệm kỳ 2026-2031 đối với việc giải quyết khiếu nại, tố cáo, kiến nghị, phản ánh của cơ quan, tổ chức, cá nhân', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/67A9222A3583D22047258E3E0007EB06/$file/NQ so 30.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\30_NQ-HĐND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=67A9222A3583D22047258E3E0007EB06', '2026-08-06 08:07:29'),
('43/NQ-HĐND', '680A53D5E0133F0447258E3E0009684E', '2026-07-21', '2026-08-20', NULL, 'HĐND Tỉnh', 'Nghị quyết HĐND xã', NULL, 'Chủ tịch HĐND Lò Minh Hùng', 'Điều chỉnh diện tích thu hồi đất để thực hiện Công trình Thủy điện Nậm Hóa 1 đã được Hội đồng nhân dân tỉnh thông qua.', 'Chưa có hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/680A53D5E0133F0447258E3E0009684E/$file/NQ so 43.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\43_NQ-HĐND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=680A53D5E0133F0447258E3E0009684E', '2026-08-06 08:02:56'),
('1367/QĐ-UBND', '680B0F9FF8A7E63447258E10002E5B9F', '2026-06-08', '2026-06-08', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'V/v ban hành Kế hoạch kiểm tra việc thực hiện hoạt động kiểm soát thủ tục hành chính trên địa bàn tỉnh năm 2026.', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/680B0F9FF8A7E63447258E10002E5B9F/$file/QD so 1367.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1367_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=680B0F9FF8A7E63447258E10002E5B9F', '2026-08-06 08:27:19');
