('10/2026/NQ-HĐND', '68114869D17FC45947258E3E000A3735', '2026-07-20', '2026-08-01', NULL, 'HĐND Tỉnh', 'Nghị quyết của HĐND tỉnh', NULL, 'Chủ tịch HĐND Lò Minh Hùng', 'Quy định mức phụ cấp, việc kiêm nhiệm chức danh và mức phụ cấp kiêm nhiệm chức danh đối với người hoạt động không chuyên trách; chức danh, số lượng, mức hỗ trợ và mức phụ cấp kiêm nhiệm chức danh đối với người tham gia hoạt động ở bản, tổ dân phố trên địa bàn tỉnh', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/68114869D17FC45947258E3E000A3735/$file/NQ so 10.2026.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\10_2026_NQ-HĐND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=68114869D17FC45947258E3E000A3735', '2026-08-06 08:08:34'),
('1724/QĐ-UBND', '6A6E9F83C440789B47258E33000FE925', '2026-07-11', '2026-07-11', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố thủ tục hành chính nội bộ mới ban hành trong lĩnh vực Lâm nghiệp và Kiểm lâm, Bảo tồn thiên nhiên và Đa dạng sinh học thuộc phạm vi chức năng quản lý nhà nước của Sở Nông nghiệp và Môi trường', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/6A6E9F83C440789B47258E33000FE925/$file/QD 1724.pdf;https://congbao.sonla.gov.vn/congbao.nsf/6A6E9F83C440789B47258E33000FE925/$file/QD 1724.F1.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1724_QĐ-UBND.pdf;D:\\Congpv\\Python\\data_congbao\\downloads\\1724_QĐ-UBND_1.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=6A6E9F83C440789B47258E33000FE925', '2026-08-06 08:10:29'),
