('1423/QĐ-UBND', '81B1EDD11BC9400047258E1800141A3D', '2026-06-13', '2026-06-13', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính được sửa đổi, bổ sung và bị bãi bỏ trong lĩnh vực Văn hóa; Du lịch thuộc phạm vi chức năng quản lý nhà nước của Sở Văn hóa, Thể thao và Du lịch', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/81B1EDD11BC9400047258E1800141A3D/$file/QD 1423.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1423_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=81B1EDD11BC9400047258E1800141A3D', '2026-08-06 08:24:36'),
('19/2026/NQ-HĐND', '821FF8BA22C45D1947258E3E000F9B60', '2026-07-21', '2026-08-01', NULL, 'HĐND Tỉnh', 'Nghị quyết của HĐND tỉnh', 'Tài nguyên-Môi trường', 'Chủ tịch HĐND Lò Minh Hùng', 'Quy định nguyên tắc, tiêu chí, định mức phân bổ nguồn vốn ngân sách Trung ương và tỷ lệ vốn đối ứng từ ngân sách địa phương thực hiện Chương trình mục tiêu quốc gia về phát triển văn hoá giai đoạn 2025 - 2035 trên địa bàn tỉnh, giai đoạn I: từ năm 2025 đến năm 2030', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/821FF8BA22C45D1947258E3E000F9B60/$file/NQ so 19.2026.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\19_2026_NQ-HĐND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=821FF8BA22C45D1947258E3E000F9B60', '2026-08-06 08:03:53'),
('44/2026/QĐ-UBND', '82E86F719C1C775F47258E48000BDD4D', '2026-08-01', '2026-08-12', NULL, 'UBND Tỉnh', 'Quyết định của UBND tỉnh', NULL, 'Phó Chủ tịch Thường trực UBND tỉnh Hà Trung Chiến', 'Bãi bỏ Quyết định số 71/2025/QĐ-UBND ngày 28 tháng 7 năm 2025 của Uỷ ban nhân dân tỉnh quy định chức năng, nhiệm vụ, quyền hạn và cơ cấu tổ chức của Sở Y tế tỉnh Sơn La.', 'Chưa có hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/82E86F719C1C775F47258E48000BDD4D/$file/QD so 44.2026.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\44_2026_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=82E86F719C1C775F47258E48000BDD4D', '2026-08-06 07:56:01'),
('45/2026/QĐ-UBND', '84111FDBC93301CC47258E48000BFE35', '2026-08-01', '2026-08-12', NULL, 'UBND Tỉnh', 'Quyết định của UBND tỉnh', NULL, 'Chủ tịch UBND Nguyễn Đình Việt', 'Bãi bỏ Quyết định số 25/2021/QĐ-UBND ngày 04 tháng 10 năm 2021 của Uỷ ban nhân dân tỉnh về việc phân cấp thẩm quyền quyết định xử lý tài sản trang bị đối với nhiệm vụ khoa học công nghệ do ngân sách nhà nước cấp thuộc địa phương quản lý.', 'Chưa có hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/84111FDBC93301CC47258E48000BFE35/$file/QD so 45.2026.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\45_2026_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=84111FDBC93301CC47258E48000BFE35', '2026-08-06 07:55:52'),
