('1824/QĐ-UBND', 'AC79AC37AD572A4047258E3C0030651A', '2026-07-22', '2026-07-22', NULL, 'UBND Tỉnh', 'Quyết định của UBND tỉnh', NULL, 'Phó Chủ tịch Thường trực UBND tỉnh Hà Trung Chiến', 'Về việc ủy quyền cho Giám đốc Sở Y tế thực hiện một số nhiệm vụ, quyền hạn trong lĩnh vực y, dược cổ truyền trên địa bàn tỉnh Sơn La', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/AC79AC37AD572A4047258E3C0030651A/$file/QD 1824.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1824_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=AC79AC37AD572A4047258E3C0030651A', '2026-08-06 08:02:25'),
('1680/QĐ-UBND', 'AD0AD508A2B8EFA347258E2D00385773', '2026-07-07', '2026-07-07', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính được sửa đổi, bổ sung và bị bãi bỏ lĩnh vực Phòng bệnh thuộc phạm vi chức năng quản lý nhà nước của Sở Y tế', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/AD0AD508A2B8EFA347258E2D00385773/$file/QD 1680.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1680_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=AD0AD508A2B8EFA347258E2D00385773', '2026-08-06 08:11:59'),
('1888/QĐ-UBND', 'AE62AFE88764751047258E4300333E38', '2026-07-24', '2026-07-24', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Nguyễn Thành Công', 'Về việc Gia hạn Giấy phép thăm dò khoáng sản số 2625/GP-UBND ngày 22/10/2025 của Chủ tịch UBND tỉnh để Công ty cổ phần tư vấn và xây dựng T26 được tiếp tục thăm dò mỏ cát tại bản Tà Đò, xã Tạ Khoa và bản Pe, xã Bắc Yên, tỉnh Sơn La đến hết ngày 07/12/2026', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/AE62AFE88764751047258E4300333E38/$file/QD 1888.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1888_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=AE62AFE88764751047258E4300333E38', '2026-08-06 08:00:30'),
('1380/QĐ-UBND', 'AFC4FF858E2CB83347258E1400162859', '2026-06-10', '2026-06-10', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Nguyễn Thành Công', 'Về việc phê duyệt Kế hoạch đấu giá quyền khai thác khoáng sản mỏ nước khoáng - nước nóng Phù Mao, xã Vân Hồ tỉnh Sơn La', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/AFC4FF858E2CB83347258E1400162859/$file/QD 1380.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1380_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=AFC4FF858E2CB83347258E1400162859', '2026-08-06 08:26:13'),
('1066/QĐ-UBND', 'B0F78E8F47EBFB5C47258DED0013902E', '2026-04-30', '2026-04-30', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Nguyễn Thành Công', 'Về việc phê duyệt Kế hoạch đấu giá quyền khai thác khoáng sản mỏ cát, sỏi làm vật liệu xây dựng thông thường trên sông Đà ở khu vực đã có kết quả thăm dò khoáng sản tại bản Nà Sàng, xã Chiềng Hoa và xã Mường Bú, tỉnh Sơn La; khu vực chưa có kết quả thăm dò khoáng sản đối với mỏ đá vôi làm vật liệu xây dựng thông thường tại bản Mạt, xã Chiềng Mung, tỉnh Sơn La (khu 2)', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/B0F78E8F47EBFB5C47258DED0013902E/$file/QD 1066_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1066_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=B0F78E8F47EBFB5C47258DED0013902E', '2026-08-06 08:43:50'),
('928/QĐ-UBND', 'B2EA8067DC12834F47258DDA00334713', '2026-04-14', '2026-04-14', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc phê duyệt danh sách công chức làm đầu mối thực hiện nhiệm vụ kiểm soát thủ tục hành chính của Sở Văn hoá, Thể thao và Du lịch', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/B2EA8067DC12834F47258DDA00334713/$file/QD 928_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\928_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=B2EA8067DC12834F47258DDA00334713', '2026-08-06 08:49:53'),
('46/2026/QĐ-UBND', 'B40C1358D5392A1447258E48000C237F', '2026-08-01', '2026-08-12', NULL, 'UBND Tỉnh', 'Quyết định của UBND tỉnh', NULL, 'Chủ tịch UBND Nguyễn Đình Việt', 'Quy định thẩm quyền quyết định phê duyệt chủ trương và dự kiến kinh phí thực hiện nhiệm vụ mua sắm, sửa chữa, cải tạo, nâng cấp tài sản, trang thiết bị; nhiệm vụ thuê hàng hóa, dịch vụ; phê duyệt chủ trương và dự kiến chi phí thực hiện nhiệm vụ sửa chữa, cải tạo, nâng cấp, mở rộng, xây dựng mới hạng mục công trình trong các dự án đã đầu tư xây dựng; phê duyệt dự kiến chi phí thực hiện hoạt động quy hoạch sử dụng nguồn chi thường xuyên ngân sách nhà nước trên địa bàn tỉnh Sơn La.', 'Chưa có hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/B40C1358D5392A1447258E48000C237F/$file/QD so 46.2026.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\46_2026_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=B40C1358D5392A1447258E48000C237F', '2026-08-06 07:55:43'),
