('1522/QĐ-UBND', 'B71B058F109F2E0347258E20002A042D', '2026-06-23', '2026-07-01', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố thủ tục hành chính mới ban hành và bị bãi bỏ lĩnh vực Tiêu chuẩn đo lường chất lượng thuộc phạm vi chức năng quản lý nhà nước của Sở Khoa học và Công nghệ', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/B71B058F109F2E0347258E20002A042D/$file/QD 1522.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1522_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=B71B058F109F2E0347258E20002A042D', '2026-08-06 08:19:34'),
('1963/QĐ-UBND', 'B73280471B2A73FC47258E490016B4B1', '2026-08-04', '2026-08-04', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'V/v ban hành Danh mục Quyết định của Ủy ban nhân dân tỉnh, Danh mục Quyết định của Chủ tịch Uỷ ban nhân dân tỉnh quy định chi tiết, quy định các nội dung được giao (đợt 6 năm 2026).', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/B73280471B2A73FC47258E490016B4B1/$file/QD so 1963.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1963_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=B73280471B2A73FC47258E490016B4B1', '2026-08-06 07:55:05'),
('1138/QĐ-UBND', 'B76AD2307E16E0A647258DF70016D70F', '2026-05-13', '2026-05-13', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính mới ban hành; được sửa đổi, bổ sung, thay thế và bãi bỏ thuộc các lĩnh vực Điện, Công nghiệp tiêu dùng, Hoá chất, Công nghiệp địa phương, Thương mại điện tử, Lưu thông hàng hoá trong nước, Xúc tiến thương mại và Xuất nhập khẩu thuộc phạm vi chức năng quản lý nhà nước của Sở Công Thương', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/B76AD2307E16E0A647258DF70016D70F/$file/QD 1138_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1138_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=B76AD2307E16E0A647258DF70016D70F', '2026-08-06 08:39:52'),
('1525/QĐ-UBND', 'B7C3ECBADA75A0B147258E2000311094', '2026-06-24', '2026-06-24', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Nguyễn Thành Công', 'Về việc phê duyệt Kế hoạch đấu giá quyền khai thác khoáng sản làm vật liệu xây dựng thông thường đối với Mỏ đất sét làm gạch ngói tại Tổ dân phố 7, xã Sông Mã, tỉnh Sơn La', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/B7C3ECBADA75A0B147258E2000311094/$file/QD 1525.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1525_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=B7C3ECBADA75A0B147258E2000311094', '2026-08-06 08:19:03'),
('927/QĐ-UBND', 'B7E416219DE2134047258DDA0032F881', '2026-04-14', '2026-04-14', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính được sửa đổi, bổ sung và bị bãi bỏ lĩnh vực Trồng trọt và Bảo vệ thực vật thuộc phạm vi chức năng quản lý nhà nước của Sở Nông nghiệp và Môi trường', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/B7E416219DE2134047258DDA0032F881/$file/QD 927_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\927_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=B7E416219DE2134047258DDA0032F881', '2026-08-06 08:50:02'),
('1438/QĐ-UBND', 'B8799FB158DEEE0E47258E180014EE4E', '2026-06-15', '2026-06-15', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính được sửa đổi, bổ sung, bị bãi bỏ tại Nghị quyết số 66.18/2026/NQ-CP và Thông tư số 09/2026/TT-BNV các lĩnh vực thuộc phạm vi chức năng quản lý nhà nước của Sở Nội vụ', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/B8799FB158DEEE0E47258E180014EE4E/$file/QD 1438.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1438_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=B8799FB158DEEE0E47258E180014EE4E', '2026-08-06 08:23:38'),
('893/QĐ-UBND', 'B95BAAAC5841A2E347258DD800349F5E', '2026-04-08', '2026-04-08', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính bị bãi bỏ trong lĩnh vực Mua bán quốc tế chuyên ngành văn hóa thuộc phạm vi chức năng quản lý nhà nước của Sở Văn hóa, Thể thao và Du lịch', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/B95BAAAC5841A2E347258DD800349F5E/$file/QD 893_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\893_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=B95BAAAC5841A2E347258DD800349F5E', '2026-08-06 08:51:27'),
('40/2026/QĐ-UBND', 'B9F09E45CA1EB82C47258E3E000FEDE9', '2026-07-24', '2026-08-02', NULL, 'UBND Tỉnh', 'Quyết định của UBND tỉnh', NULL, 'Phó Chủ tịch UBND Nguyễn Minh Tiến', 'Ban hành Quy chế quản lý các công trình ghi công liệt sĩ, mộ liệt sĩ trên địa bàn tỉnh Sơn La', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/B9F09E45CA1EB82C47258E3E000FEDE9/$file/QD so 40.2026.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\40_2026_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=B9F09E45CA1EB82C47258E3E000FEDE9', '2026-08-06 08:00:16'),
('1050/QĐ-UBND', 'BA2736D863D2148347258DED000FFF86', '2026-04-29', '2026-04-29', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính được Chủ tịch UBND tỉnh ủy quyền trong lĩnh vực Chăn nuôi, Thú y, Thủy sản thuộc phạm vi chức năng quản lý nhà nước của Sở Nông nghiệp và Môi trường', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/BA2736D863D2148347258DED000FFF86/$file/QD 1050_signed.pdf;https://congbao.sonla.gov.vn/congbao.nsf/BA2736D863D2148347258DED000FFF86/$file/QD 1050.F1_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1050_QĐ-UBND.pdf;D:\\Congpv\\Python\\data_congbao\\downloads\\1050_QĐ-UBND_1.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=BA2736D863D2148347258DED000FFF86', '2026-08-06 08:44:12'),
('1890/QĐ-UBND', 'BAAB42C6DFE06E8847258E4300324423', '2026-07-28', '2026-07-28', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Chủ tịch UBND Nguyễn Đình Việt', 'Về việc chấp thuận chủ trương đầu tư đồng thời chấp thuận nhà đầu tư dự án Nhà máy chế biến sâu cà phê Detech tại xã Bình Thuận, tỉnh Sơn La', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/BAAB42C6DFE06E8847258E4300324423/$file/QD 1890.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1890_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=BAAB42C6DFE06E8847258E4300324423', '2026-08-06 07:58:02'),
('1132/QĐ-UBND', 'BAEAB3F24E2C475147258DF7001669C6', '2026-05-12', '2026-05-12', NULL, 'UBND Tỉnh', 'Quyết định của UBND tỉnh', NULL, 'Phó Chủ tịch UBND Nguyễn Thành Công', 'Phê duyệt Quy trình vận hành hồ chứa thủy điện Xím Vàng 2 thuộc xã Xím Vàng, xã Tà Xùa và xã Pắc Ngà, tỉnh Sơn La', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/BAEAB3F24E2C475147258DF7001669C6/$file/QD 1132_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1132_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=BAEAB3F24E2C475147258DF7001669C6', '2026-08-06 08:40:42'),
('13/2026/NQ-HĐND', 'BB1F6CEFBE1DA54347258E3E000AB287', '2026-07-21', '2026-08-01', NULL, 'HĐND Tỉnh', 'Nghị quyết của HĐND tỉnh', NULL, 'Chủ tịch HĐND Lò Minh Hùng', 'Quy định chế độ mua sắm, thủ tục cấp phát phù hiệu, cờ hiệu, cấp hiệu, biển hiệu và trang phục đối với công chức làm việc tại Chi cục Quản lý thị trường trực thuộc Sở Công Thương.', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/BB1F6CEFBE1DA54347258E3E000AB287/$file/NQ so 13.2026.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\13_2026_NQ-HĐND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=BB1F6CEFBE1DA54347258E3E000AB287', '2026-08-06 08:05:27'),
('04/2026/NQ-HĐND', 'BC01BB5A70A8181547258E25000A66D6', '2026-05-22', '2026-07-02', NULL, 'HĐND Tỉnh', 'Nghị quyết của HĐND tỉnh', NULL, 'Chủ tịch HĐND Lò Minh Hùng', 'Bãi bỏ Nghị quyết số 121/2025/NQ-HĐND ngày 17 tháng 7 năm 2025 của Hội đồng nhân dân tỉnh quy định thẩm quyền quyết định phê duyệt nhiệm vụ và dự toán kinh phí thực hiện mua sắm, sửa chữa, cải tạo, nâng cấp tài sản, trang thiết bị; chi thuê hàng hóa, dịch vụ; sửa chữa, cải tạo, nâng cấp, mở rộng, xây dựng mới hạng mục công trình trong các dự án đã đầu tư xây dựng sử dụng nguồn chi thường xuyên ngân sách nhà nước trên địa bàn tỉnh Sơn La', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/BC01BB5A70A8181547258E25000A66D6/$file/NQ so 04.2026_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\04_2026_NQ-HĐND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=BC01BB5A70A8181547258E25000A66D6', '2026-08-06 08:36:54'),
('957/QĐ-UBND', 'BCFFF44A0716C6E747258DDF000B63BD', '2026-04-17', '2026-04-17', NULL, 'UBND Tỉnh', 'Quyết định của UBND tỉnh', NULL, 'Phó Chủ tịch UBND Nguyễn Thành Công', 'Phê duyệt Phương án bảo vệ đập, hồ chứa nước thủy điện Pá Chiến', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/BCFFF44A0716C6E747258DDF000B63BD/$file/QD 957_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\957_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=BCFFF44A0716C6E747258DDF000B63BD', '2026-08-06 08:49:05'),
('1120/QĐ-UBND', 'BD027B1CA68403CE47258DF60036B573', '2026-05-12', '2026-05-12', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Chủ tịch UBND Nguyễn Đình Việt', 'Về việc miễn nhiệm và thu hồi thẻ giám định viên tư pháp lĩnh vực Văn hóa, Thể thao và Du lịch', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/BD027B1CA68403CE47258DF60036B573/$file/QD 1120_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1120_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=BD027B1CA68403CE47258DF60036B573', '2026-08-06 08:41:37'),
