('18/NQ-HĐND', 'C03487568B1FF46C47258E27002A3B2F', '2026-06-26', '2026-06-26', NULL, 'HĐND xã Chiềng Mai', 'Nghị quyết HĐND xã', NULL, 'Chủ tịch HĐND Hà Văn Bình', 'Phê chuẩn điều chỉnh quyết toán ngân sách địa phương năm 2025', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/C03487568B1FF46C47258E27002A3B2F/$file/NQ 18.CMai.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\18_NQ-HĐND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=C03487568B1FF46C47258E27002A3B2F', '2026-08-06 08:17:17'),
('1633/QĐ-UBND', 'C0617F31D54EF45E47258E2D0011CBD7', '2026-07-03', '2026-07-03', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố thủ tục hành chính nội bộ mới ban hành lĩnh vực Địa chất và Khoáng sản thuộc phạm vi chức năng quản lý nhà nước của Sở Nông nghiệp và Môi trường', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/C0617F31D54EF45E47258E2D0011CBD7/$file/QD 1633.pdf;https://congbao.sonla.gov.vn/congbao.nsf/C0617F31D54EF45E47258E2D0011CBD7/$file/QD 1633.F1.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1633_QĐ-UBND.pdf;D:\\Congpv\\Python\\data_congbao\\downloads\\1633_QĐ-UBND_1.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=C0617F31D54EF45E47258E2D0011CBD7', '2026-08-06 08:13:00'),
('1708/QĐ-UBND', 'C115A27CC1F52C4A47258E33000DF2A8', '2026-07-09', '2026-07-09', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính được sửa đổi, bổ sung, thay thế trong lĩnh vực Đường bộ, Quản lý chất lượng công trình xây dựng thuộc phạm vi chức năng quản lý nhà nước của Sở Xây dựng', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/C115A27CC1F52C4A47258E33000DF2A8/$file/QD 1708.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1708_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=C115A27CC1F52C4A47258E33000DF2A8', '2026-08-06 08:10:55'),
('1332/QĐ-UBND', 'C1265C2556BFD53447258E0B0036B388', '2026-06-03', '2026-06-03', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính mới ban hành; được sửa đổi, bổ sung trong lĩnh vực Quản lý chất lượng nông lâm sản và thủy sản thuộc phạm vi chức năng quản lý nhà nước của Sở Nông nghiệp và Môi trường', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/C1265C2556BFD53447258E0B0036B388/$file/QD 1332_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1332_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=C1265C2556BFD53447258E0B0036B388', '2026-08-06 08:29:26'),
('1809/QĐ-UBND', 'C15936AF943E1E2147258E3B000C11DC', '2026-07-20', '2026-07-20', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Nguyễn Minh Tiến', 'Về việc phê duyệt điều chỉnh, bổ sung danh mục quy chuẩn, tiêu chuẩn áp dụng cho dự án Đầu tư xây dựng tuyến đường bộ cao tốc Hòa Bình - Mộc Châu, đoạn tuyến thuộc địa bàn tỉnh Sơn La tại Phụ lục của Quyết định số 460/QĐUBND ngày 18/3/2024; số 2630/QĐ-UBND ngày 10/12/2024 và số 533/QĐUBND ngày 10/3/2025 của Chủ tịch UBND tỉnh Sơn La', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/C15936AF943E1E2147258E3B000C11DC/$file/QD 1809.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1809_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=C15936AF943E1E2147258E3B000C11DC', '2026-08-06 08:07:36'),
('993/QĐ-UBND', 'C1DCA3253B6B036347258DE2002ACD9C', '2026-04-22', '2026-04-22', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố thủ tục hành chính nội bộ được sửa đổi, bổ sung trong lĩnh vực Nhà ở thuộc phạm vi chức năng quản lý nhà nước của Sở Xây dựng', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/C1DCA3253B6B036347258DE2002ACD9C/$file/QD 993_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\993_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=C1DCA3253B6B036347258DE2002ACD9C', '2026-08-06 08:46:27'),
('1333/QĐ-UBND', 'C43C8C0E70030C2A47258E0B0036EAD5', '2026-06-03', '2026-06-03', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính mới ban hành; được sửa đổi, bổ sung và bị bãi bỏ trong lĩnh vực Khoa học và Công nghệ, Trồng trọt và Bảo vệ thực vật, Biến đổi khí hậu thuộc phạm vi chức năng quản lý nhà nước của Sở Nông nghiệp và Môi trường', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/C43C8C0E70030C2A47258E0B0036EAD5/$file/QD 1333_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1333_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=C43C8C0E70030C2A47258E0B0036EAD5', '2026-08-06 08:29:09'),
('1272/QĐ-UBND', 'C505750331D5446047258E06001695BD', '2026-05-29', '2026-05-29', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc bổ nhiệm Thừa phát lại', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/C505750331D5446047258E06001695BD/$file/QD 1272_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1272_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=C505750331D5446047258E06001695BD', '2026-08-06 08:33:27'),
('1882/QĐ-UBND', 'C59430202B0827E247258E420032018B', '2026-07-28', '2026-07-28', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính mới ban hành, được sửa đổi, bổ sung, thay thế và bị bãi bỏ trong lĩnh vực Đường thủy nội địa thuộc phạm vi chức năng quản lý nhà nước của Sở Xây dựng', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/C59430202B0827E247258E420032018B/$file/QD 1882.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1882_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=C59430202B0827E247258E420032018B', '2026-08-06 07:58:39'),
('1896/QĐ-UBND', 'C6146F72C1879A8447258E4300170AB0', '2026-07-28', '2026-09-01', NULL, 'UBND Tỉnh', 'Quyết định của UBND tỉnh', NULL, 'Phó Chủ tịch UBND Nguyễn Thành Công', 'V/v định giá cụ thể nước sạch sinh hoạt tập trung nông thôn đối với 12 công trình loại hình bơm dẫn do Trung tâm Nước và Quan trắc môi trường quản lý.', 'Chưa có hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/C6146F72C1879A8447258E4300170AB0/$file/QD so 1896.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1896_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=C6146F72C1879A8447258E4300170AB0', '2026-08-06 07:57:39'),
('929/QĐ-UBND', 'C624C921162D263A47258DDA00337B0D', '2026-04-15', '2026-04-15', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Chủ tịch UBND Nguyễn Đình Việt', 'Về việc ủy quyền cho Giám đốc Sở Tư pháp quyết định công nhận xã, phường đạt chuẩn tiếp cận pháp luật trên địa bàn tỉnh Sơn La', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/C624C921162D263A47258DDA00337B0D/$file/QD 929_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\929_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=C624C921162D263A47258DDA00337B0D', '2026-08-06 08:49:35'),
('1703/QĐ-UBND', 'C7944F7A256F09A747258E2F000AF9F9', '2026-07-08', '2026-07-08', NULL, 'UBND Tỉnh', 'Quyết định của UBND tỉnh', NULL, 'Phó Chủ tịch UBND Nguyễn Minh Tiến', 'Phê duyệt đề cương và dự toán lập điều chỉnh Chương trình phát triển đô thị tỉnh Sơn La đến năm 2030', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/C7944F7A256F09A747258E2F000AF9F9/$file/QD 1703.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1703_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=C7944F7A256F09A747258E2F000AF9F9', '2026-08-06 08:11:04'),
('36/NQ-HĐND', 'C961D5FAB652681147258E3E000871B4', '2026-07-20', '2026-07-20', NULL, 'HĐND Tỉnh', 'Nghị quyết của HĐND tỉnh', NULL, 'Chủ tịch HĐND Lò Minh Hùng', 'Kế hoạch đầu tư công trung hạn vốn ngân sách địa phương giai đoạn 2026 - 2030.', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/C961D5FAB652681147258E3E000871B4/$file/NQ so 36.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\36_NQ-HĐND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=C961D5FAB652681147258E3E000871B4', '2026-08-06 08:06:21'),
('1728/QĐ-UBND', 'C96CD5E709297C1F47258E33000F1F4E', '2026-07-11', '2026-07-11', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính bị bãi bỏ trong lĩnh vực Dân số thuộc phạm vi chức năng quản lý nhà nước của Sở Y tế tỉnh', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/C96CD5E709297C1F47258E33000F1F4E/$file/QD 1728.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1728_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=C96CD5E709297C1F47258E33000F1F4E', '2026-08-06 08:10:02'),
('1291/QĐ-UBND', 'C9BFD708F8F4BFB847258E0A000D8C36', '2026-05-31', '2026-05-31', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính bị bãi bỏ trong lĩnh vực Vật liệu xây dựng thuộc phạm vi chức năng quản lý nhà nước của Sở Xây dựng', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/C9BFD708F8F4BFB847258E0A000D8C36/$file/QD 1291_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1291_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=C9BFD708F8F4BFB847258E0A000D8C36', '2026-08-06 08:32:48');
