('1602/QĐ-UBND', 'CA0F7F23587802C147258E27002D831D', '2026-07-01', '2026-07-01', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Nguyễn Thành Công', 'Ban hành Kế hoạch tổ chức cuộc thi trực tuyến “Tìm hiểu công tác cải cách hành chính tỉnh Sơn La” năm 2026', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/CA0F7F23587802C147258E27002D831D/$file/QD 1602.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1602_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=CA0F7F23587802C147258E27002D831D', '2026-08-06 08:15:22'),
('1295/QĐ-UBND', 'CAF42DE04170836347258E0A000DB7AE', '2026-06-01', '2026-06-01', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính mới ban hành; được sửa đổi, bổ sung và bị bãi bỏ trong lĩnh vực Địa chất và Khoáng sản, Đất đai thuộc phạm vi chức năng quản lý nhà nước của Sở Nông nghiệp và Môi trường', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/CAF42DE04170836347258E0A000DB7AE/$file/QD 1295_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1295_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=CAF42DE04170836347258E0A000DB7AE', '2026-08-06 08:32:16'),
('1744/QĐ-UBND', 'CB0AEF89D7F772C447258E3300119710', '2026-07-13', '2026-07-13', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch Thường trực UBND tỉnh Hà Trung Chiến', 'Về việc phê duyệt điều chỉnh Báo cáo kinh tế kỹ thuật đầu tư xây dựng công trình Bảo tồn, tôn tạo khu di tích lịch sử Cây Me - Nơi thành lập chi bộ đầu tiên của Đảng bộ tỉnh Sơn La', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/CB0AEF89D7F772C447258E3300119710/$file/QD 1744.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1744_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=CB0AEF89D7F772C447258E3300119710', '2026-08-06 08:09:20'),
('1085/QĐ-UBND', 'CB8E337A9743692347258DEF002A5571', '2026-05-05', '2026-05-05', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố danh mục thủ tục hành chính được sửa đổi, bổ sung, thay thế và bị bãi bỏ lĩnh vực Lao động, tiền lương và Quản lý lao động ngoài nước tại Nghị quyết số 66.16/2026/NQ-CP về cắt giảm, đơn giản hóa thủ tục hành chính, quy định liên quan đến hoạt động sản xuất, kinh doanh thuộc phạm vi chức năng quản lý nhà nước của Sở Nội vụ', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/CB8E337A9743692347258DEF002A5571/$file/QD 1085_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1085_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=CB8E337A9743692347258DEF002A5571', '2026-08-06 08:42:45'),
('42/2026/QĐ-UBND', 'CD6ACB0404C4B52D47258E420011B16D', '2026-07-27', '2026-08-06', NULL, 'UBND Tỉnh', 'Quyết định của UBND tỉnh', NULL, 'Phó Chủ tịch Thường trực UBND tỉnh Hà Trung Chiến', 'Quy định cụ thể danh mục trang cấp đồ dùng cá nhân, học phẩm cho học sinh trường phổ thông nội trú và trường phổ thông nội trú tại các xã biên giới trên địa bàn tỉnh Sơn La.', 'Chưa có hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/CD6ACB0404C4B52D47258E420011B16D/$file/QD so 42.2026.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\42_2026_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=CD6ACB0404C4B52D47258E420011B16D', '2026-08-06 07:58:57'),
('1452/QĐ-UBND', 'CD7A584B35EC525C47258E1A002EAFE4', '2026-06-17', '2026-07-01', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính mới, Danh mục thủ tục hành chính được sửa đổi và bị bãi bỏ trong lĩnh vực đấu giá tài sản thuộc phạm vi chức năng quản lý nhà nước của Sở Tư pháp', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/CD7A584B35EC525C47258E1A002EAFE4/$file/QD 1452.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1452_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=CD7A584B35EC525C47258E1A002EAFE4', '2026-08-06 08:23:12'),
('17/2026/NQ-HĐND', 'CF6585D0839CACD947258E3E00078A96', '2026-07-21', '2026-08-01', NULL, 'HĐND Tỉnh', 'Nghị quyết của HĐND tỉnh', NULL, 'Chủ tịch HĐND Lò Minh Hùng', 'Ban hành Quy định nội dung và mức chi quản lý hoạt động khoa học, công nghệ và đổi mới sáng tạo có sử dụng ngân sách nhà nước thuộc phạm vi quản lý của tỉnh.', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/CF6585D0839CACD947258E3E00078A96/$file/NQ so 17.2026.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\17_2026_NQ-HĐND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=CF6585D0839CACD947258E3E00078A96', '2026-08-06 08:04:45'),
('97/NQ-HĐND', 'CFCD609AF71D6CCF47258DDA00175690', '2026-03-31', '2026-03-31', NULL, 'HĐND Tỉnh', 'Nghị quyết của Thường trực HĐND tỉnh', NULL, 'Chủ tịch HĐND Lò Minh Hùng', 'Phê chuẩn kết quả bầu Chủ tịch Hội đồng nhân dân xã Long Hẹ khoá XXII, nhiệm kỳ 2026 - 2031', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/CFCD609AF71D6CCF47258DDA00175690/$file/NQ 97.tinh_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\97_NQ-HĐND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=CFCD609AF71D6CCF47258DDA00175690', '2026-08-06 08:52:29'),
('1643/QĐ-UBND', 'D086C249A80DD16747258E2D0035EEC7', '2026-07-03', '2026-07-03', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính mới ban hành trong lĩnh vực Trồng trọt và Bảo vệ thực vật thuộc phạm vi chức năng quản lý nhà nước của Sở Nông nghiệp và Môi trường', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/D086C249A80DD16747258E2D0035EEC7/$file/QD 1643.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1643_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=D086C249A80DD16747258E2D0035EEC7', '2026-08-06 08:12:38'),
('1613/QĐ-UBND', 'D0E55215D16508B747258E280012E7C1', '2026-07-01', '2026-07-01', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Nguyễn Thành Công', 'Về việc công nhận kết quả thăm dò khoáng sản mỏ cát tại bản Mé Bon và bản Xum Côn, xã Sông Mã, tỉnh Sơn La (trữ lượng tính đến tháng 6 năm 2026)', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/D0E55215D16508B747258E280012E7C1/$file/QD 1613.pdf;https://congbao.sonla.gov.vn/congbao.nsf/D0E55215D16508B747258E280012E7C1/$file/QD 1613.F1.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1613_QĐ-UBND.pdf;D:\\Congpv\\Python\\data_congbao\\downloads\\1613_QĐ-UBND_1.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=D0E55215D16508B747258E280012E7C1', '2026-08-06 08:14:31'),
('1232/QĐ-UBND', 'D1D096065D86E61047258E030029907B', '2026-05-26', '2026-05-26', NULL, 'UBND Tỉnh', 'Quyết định của UBND tỉnh', NULL, 'Phó Chủ tịch UBND Nguyễn Minh Tiến', 'Phê duyệt nhiệm vụ quy hoạch chung xã Bó Sinh, tỉnh Sơn La đến năm 2045', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/D1D096065D86E61047258E030029907B/$file/QD 1232_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1232_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=D1D096065D86E61047258E030029907B', '2026-08-06 08:35:39'),
('32/NQ-HĐND', 'D27033D33E0EB98647258E3E00083858', '2026-07-20', '2026-07-20', NULL, 'HĐND Tỉnh', 'Nghị quyết của HĐND tỉnh', NULL, 'Chủ tịch HĐND Lò Minh Hùng', 'Về việc quyết định biên chế cán bộ, công chức trong các cơ quan của chính quyền cấp tỉnh và tổng biên chế cán bộ, công chức của chính quyền địa phương cấp xã năm 2026.', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/D27033D33E0EB98647258E3E00083858/$file/NQ so 32.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\32_NQ-HĐND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=D27033D33E0EB98647258E3E00083858', '2026-08-06 08:07:05'),
