('1213/QĐ-UBND', 'D431B65869E7DE1547258E02000C04E6', '2026-05-22', '2026-05-22', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính mới ban hành lĩnh vực Biến đổi khí hậu thuộc phạm vi chức năng quản lý nhà nước của Sở Nông nghiệp và Môi trường', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/D431B65869E7DE1547258E02000C04E6/$file/QD 1213_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1213_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=D431B65869E7DE1547258E02000C04E6', '2026-08-06 08:36:35'),
('1626/QĐ-UBND', 'D440F4137973732247258E2D0011150D', '2026-07-02', '2026-07-02', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính được sửa đổi, bổ sung và bị bãi bỏ trong lĩnh vực Quy hoạch đô thị và Nông thôn, Kiến trúc thuộc phạm vi chức năng quản lý nhà nước của Sở Xây dựng', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/D440F4137973732247258E2D0011150D/$file/QD 1626.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1626_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=D440F4137973732247258E2D0011150D', '2026-08-06 08:13:43'),
('1702/QĐ-UBND', 'D62693EF6C1081BA47258E2F000AC805', '2026-07-08', '2026-07-08', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Chủ tịch UBND Nguyễn Đình Việt', 'Thành lập 04 Tổ công tác tháo gỡ khó khăn, vướng mắc đối với các dự án đầu tư sử dụng vốn nhà nước và các dự án đầu tư ngoài ngân sách trên địa bàn tỉnh Sơn La', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/D62693EF6C1081BA47258E2F000AC805/$file/QD 1702.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1702_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=D62693EF6C1081BA47258E2F000AC805', '2026-08-06 08:11:14'),
('894/QĐ-UBND', 'D68E29788FF8631A47258DD80034F087', '2026-04-08', '2026-04-15', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính mới ban hành, được sửa đổi, bổ sung và bị bãi bỏ lĩnh vực Văn bằng, chứng chỉ thuộc phạm vi chức năng quản lý nhà nước của Sở Giáo dục và Đào tạo', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/D68E29788FF8631A47258DD80034F087/$file/QD 894_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\894_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=D68E29788FF8631A47258DD80034F087', '2026-08-06 08:51:18'),
('1833/QĐ-UBND', 'D72E022952E0EF3D47258E3D00116653', '2026-07-23', '2026-07-23', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Nguyễn Thành Công', 'Về việc công bố kết thúc tình huống khẩn cấp về thiên tai tại bản Nong Sơn, Cao Sơn xã Chiềng Sung, bản Ngậm xã Bắc Yên và các xã: Tà Xùa, Mường La, Mường Bú, Ngọc Chiến', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/D72E022952E0EF3D47258E3D00116653/$file/QD 1833.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1833_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=D72E022952E0EF3D47258E3D00116653', '2026-08-06 08:01:43'),
