('861/QĐ-UBND', 'DAA57A54D71E61EF47258DD8001722A0', '2026-04-02', '2026-04-02', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính mới ban hành; sửa đổi, bổ sung và bị bãi bỏ lĩnh vực Thủy sản và Kiểm ngư, lĩnh vực Chăn nuôi thuộc phạm vi chức năng quản lý nhà nước của Sở Nông nghiệp và Môi trường', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/DAA57A54D71E61EF47258DD8001722A0/$file/QD 861_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\861_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=DAA57A54D71E61EF47258DD8001722A0', '2026-08-06 08:52:03'),
('15/CT-UBND', 'DAAB922779396E9447258E0A000C81B9', '2026-05-30', '2026-05-30', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Chủ tịch UBND Nguyễn Đình Việt', 'Về việc tổ chức Kỳ thi tốt nghiệp trung học phổ thông, tuyển sinh đại học, giáo dục nghề nghiệp năm 2026 và tuyển sinh vào các lớp đầu cấp năm học 2026-2027 trên địa bàn tỉnh Sơn La', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/DAAB922779396E9447258E0A000C81B9/$file/CT 15_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\15_CT-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=DAAB922779396E9447258E0A000C81B9', '2026-08-06 08:33:06'),
