('43/2026/QĐ-UBND', 'F7A08E6E82979F2747258E440025DEF4', '2026-07-29', '2026-08-08', NULL, 'UBND Tỉnh', 'Quyết định của UBND tỉnh', NULL, 'Phó Chủ tịch Thường trực UBND tỉnh Hà Trung Chiến', 'Quy định địa bàn làm căn cứ xác định học sinh, học viên không thể đi đến trường và trở về nhà trong ngày theo quy định tại Nghị định số 66/2025/NĐ-CP của Chính phủ trên địa bàn tỉnh Sơn La.', 'Chưa có hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/F7A08E6E82979F2747258E440025DEF4/$file/QD so 43.2026.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\43_2026_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=F7A08E6E82979F2747258E440025DEF4', '2026-08-06 07:56:55'),
('1425/QĐ-UBND', 'F878B2C2DFABBF4D47258E1800148AF5', '2026-06-13', '2026-06-13', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính mới ban hành, được sửa đổi, bổ sung, thay thế và bãi bỏ thuộc lĩnh vực Hoá chất, Xuất nhập khẩu, Vật liệu nổ công nghiệp, tiền chất thuốc nổ, Khoáng sản, Vận chuyển hàng hoá nguy hiểm, Công nghiệp tiêu dùng thuộc phạm vi chức năng quản lý nhà nước của Sở Công Thương', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/F878B2C2DFABBF4D47258E1800148AF5/$file/QD 1425.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1425_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=F878B2C2DFABBF4D47258E1800148AF5', '2026-08-06 08:24:08'),
('1483/QĐ-UBND', 'F8A7E1B1D113936B47258E1E0032A4F8', '2026-06-21', '2026-06-21', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Chủ tịch UBND Nguyễn Đình Việt', 'Phê duyệt kết quả lựa chọn nhà đầu tư dự án Khu đô thị mới lân cận trung tâm du lịch trọng điểm tại phường Vân Sơn', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/F8A7E1B1D113936B47258E1E0032A4F8/$file/QD 1483.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1483_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=F8A7E1B1D113936B47258E1E0032A4F8', '2026-08-06 08:21:31'),
('966/QĐ-UBND', 'F967AC6603432B3F47258DE1000C73F9', '2026-04-20', '2026-04-20', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính được Chủ tịch UBND tỉnh ủy quyền trong lĩnh vực Trồng trọt và Bảo vệ thực vật thuộc phạm vi chức năng quản lý nhà nước của Sở Nông nghiệp và Môi trường', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/F967AC6603432B3F47258DE1000C73F9/$file/QD 966_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\966_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=F967AC6603432B3F47258DE1000C73F9', '2026-08-06 08:48:28'),
('968/QĐ-UBND', 'F97DEEE1032E049F47258DE1000ED0FE', '2026-04-20', '2026-04-20', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính mới ban hành, sửa đổi, bổ sung và bị bãi bỏ trong lĩnh vực Hoạt động khoa học và công nghệ; Sở hữu trí tuệ thuộc phạm vi chức năng quản lý của Sở Khoa học và Công nghệ', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/F97DEEE1032E049F47258DE1000ED0FE/$file/QD 968_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\968_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=F97DEEE1032E049F47258DE1000ED0FE', '2026-08-06 08:48:11'),
('1200/QĐ-UBND', 'F9B6799D3CB113FA47258DFE000B7A21', '2026-05-20', '2026-05-20', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính bị bãi bỏ trong lĩnh vực tiêu chuẩn đo lường chất lượng thuộc phạm vi chức năng quản lý của Sở Khoa học và Công nghệ', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/F9B6799D3CB113FA47258DFE000B7A21/$file/QD 1200_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1200_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=F9B6799D3CB113FA47258DFE000B7A21', '2026-08-06 08:37:32'),
('1265/QĐ-UBND', 'FA85A63FB537F67047258E0600038EC9', '2026-05-28', '2026-05-28', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch Thường trực UBND tỉnh Hà Trung Chiến', 'V/v ban hành Kế hoạch tổ chức Ngày Quốc tế Yoga tại tỉnh Sơn La năm 2026.', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/FA85A63FB537F67047258E0600038EC9/$file/QD so 1265_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1265_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=FA85A63FB537F67047258E0600038EC9', '2026-08-06 08:34:06'),
('19/NQ-HĐND', 'FABFEDE43BDF843A47258E27002D20A6', '2026-06-26', '2026-06-26', NULL, 'HĐND xã Kim Bon', 'Nghị quyết HĐND xã', NULL, 'Chủ tịch HĐND Hà Đình Hưng', 'Về việc phê duyệt phương án sử dụng tiền dịch vụ môi trường rừng xã Kim Bon phục vụ công tác quản lý, bảo vệ rừng năm 2026', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/FABFEDE43BDF843A47258E27002D20A6/$file/NQ 19.KBon.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\19_NQ-HĐND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=FABFEDE43BDF843A47258E27002D20A6', '2026-08-06 08:16:58'),
('1375/QĐ-UBND', 'FCE6EBEB35F7821E47258E1400149A67', '2026-06-09', '2026-06-09', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Đặng Ngọc Hậu', 'Về việc công bố Danh mục thủ tục hành chính nội bộ mới ban hành lĩnh vực Quản lý công sản thuộc phạm vi chức năng quản lý nhà nước của Sở Tài chính', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/FCE6EBEB35F7821E47258E1400149A67/$file/QD 1375.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1375_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=FCE6EBEB35F7821E47258E1400149A67', '2026-08-06 08:26:44'),
('880/QĐ-UBND', 'FD29A29CA54BB05447258DD80030AD2A', '2026-04-06', '2026-04-06', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Nguyễn Thành Công', 'Về việc đưa mỏ cát tại khu vực bản Nà Sàng, xã Chiềng Hoa và xã Mường Chùm, huyện Mường La (nay là xã Chiềng Hoa và xã Mường Bú), tỉnh Sơn La ra khỏi khu vực không đấu giá quyền khai thác khoáng sản thuộc thẩm quyền cấp phép của UBND tỉnh theo Quyết định số 2845/QĐ-UBND ngày 19/11/2021', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/FD29A29CA54BB05447258DD80030AD2A/$file/QD 880_signed.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\880_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=FD29A29CA54BB05447258DD80030AD2A', '2026-08-06 08:51:44'),
('1870/QĐ-UBND', 'FE7A14B51807B02547258E42002D87CD', '2026-07-27', '2026-07-27', NULL, 'UBND Tỉnh', 'Quyết định của Chủ tịch UBND tỉnh', NULL, 'Phó Chủ tịch UBND Nguyễn Thành Công', 'Về việc thu hồi 16.472 m2 đất tại tổ 6, phường Chiềng Sinh, tỉnh Sơn La của Công ty TNHH một thành viên Quốc Cường Tây Bắc do tự nguyện trả lại đất để giao cho Trung tâm Phát triển quỹ đất tỉnh Sơn La quản lý', 'Đang hiệu lực', NULL, NULL, 'https://congbao.sonla.gov.vn/congbao.nsf/FE7A14B51807B02547258E42002D87CD/$file/QD 1870.pdf', 'D:\\Congpv\\Python\\data_congbao\\downloads\\1870_QĐ-UBND.pdf', 'https://congbao.sonla.gov.vn/congbao.nsf/NoiDung?openForm&ParentUNID=FE7A14B51807B02547258E42002D87CD', '2026-08-06 07:59:47');
